(()=>{
const keys=Object.keys(localStorage);
const chatKeys=keys.filter(k=>/chat|assistant|conversation|thread/i.test(k));
const out={keyCount:keys.length,chatKeys:chatKeys.map(k=>({key:k,bytes:(localStorage.getItem(k)||'').length}))};
const summary={};
for(const k of chatKeys){try{const v=JSON.parse(localStorage.getItem(k));
 summary[k]={shape:Array.isArray(v)?'array':typeof v,
   projectIds:v&&typeof v==='object'&&!Array.isArray(v)?Object.keys(v).slice(0,8):null,
   threads:v&&v.threads?Object.keys(v.threads).length:null};}catch(e){summary[k]={unparsed:String(e).slice(0,80)}}}
out.summary=summary;
return JSON.stringify(out)})()

(()=>{window.__qaArch=null;(async()=>{try{
const h=await import('/src/studio/assistant/chatHistory.ts');
const store=await import('/src/studio/store.ts');
const jobId=store.useStudio.getState().job.id;
const a=await h.readChatArchive(jobId);
window.__qaArch={jobId,archivePresent:!!a,activeId:a?.activeId??null,threadCount:a?.threads?.length??0,
threads:(a?.threads??[]).map(t=>({id:t.id,entries:t.entries.length,assistantTexts:t.entries.filter(e=>e.kind==='assistant').map(e=>({chars:(e.text||'').length,head:(e.text||'').slice(0,160)}))}))};
}catch(e){window.__qaArch={error:String(e)}}})();return 'reading archive'})()
